/// <summary>
///  AVA/WEN 2024/06/17    AVA_012052_DefaultValuesWarehouseJourPositions
/// </summary>
/// <param name="sender">FormDataObject</param>
/// <param name="e">FormDataFieldEventArgs</param>
[   SuppressBPWarning("BPParameterNotUsed", "Parameter required by the event interface"),
    FormDataFieldEventHandler(formDataFieldStr(InventJournalTransfer, InventJournalTrans, ItemId), FormDataFieldEventType::Modified)]
public static void ItemId_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
{
    FormDataSource  inventDimReceiptDS;
    InventDim       inventDimREceipt;
    FormDataSource inventTransDS = sender.datasource();
    InventJournalTrans inventJournalTrans = inventTransDS.cursor();

    if (inventJournalTrans.JournalType == InventJournalType::Transfer)
    {
        inventDimReceiptDS = sender.datasource().formRun().dataSource(formDataSourceStr(InventJournalTransfer,InventDimReceipt));
        inventDimREceipt = inventDimReceiptDS.cursor();
        inventDimReceipt.data(inventJournalTrans.toInventDim());
        inventDimReceipt.write();
        inventDimReceiptDs.research();
    }

}
